--- 请求录像
function UIFightTeamRecommendLineupNode:OnVideoBtnClicked()
    local succeed = false
    local operation = GameUtils.Request(Interfaces.MainQuestRecommendLineupBattleRecord, {questId = self.data.questId, videoId = self.data.videoId}, function(request, response)
        succeed = true
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data.battleData
        self.battleRecord = jsonData
        FightPreWarMgr:GetInstance():FightReplay(self.battleRecord)
    end)
end

return UIFightTeamRecommendLineupNode